<script setup lang="ts">
const s=useAtelier(),audio=useAudio(),ready=ref(false),progress=ref(0),error=ref(''),tab=ref('Paint'),hotspot=ref(''),viewer=ref(0)
const paints=[{name:'Verde Atelier',hex:'#a2b368'},{name:'Nero Noctis',hex:'#181c1d'},{name:'Rosso Mars',hex:'#ac252a'},{name:'Bianco',hex:'#e4e2d8'},{name:'Blu',hex:'#254d73'},{name:'Grigio',hex:'#747875'}]
const paintName=computed(()=>paints.find(p=>p.hex===s.paint.value)?.name||'Signature finish')
onMounted(()=>{s.motion.value=!matchMedia('(prefers-reduced-motion: reduce)').matches})
function start(){s.sound.value=true;s.engine.value=!s.engine.value;audio.sync()}
</script>
<template><div><AtelierHeader />
 <div class="scene-wrap"><ClientOnly><VehicleScene :key="viewer" @ready="ready=true" @progress="progress=$event" @error="error=$event" /></ClientOnly><div class="scene-shade" /></div>
 <div v-if="!ready" class="loader"><div class="wordmark">VELOCITY 3<span>AUTOMOBILI</span></div><template v-if="!error"><p>{{progress<35?'INITIALIZING':progress<65?'PREPARING MATERIALS':progress<100?'SETTING LIGHTS':'READY'}}</p><strong>{{String(progress).padStart(2,'0')}}<small>%</small></strong><div class="progress-track"><i :style="{width:progress+'%'}" /></div></template><template v-else><p>THE SHOWROOM COULD NOT START</p><p>{{error}}</p><button class="outline" @click="error='';viewer++;progress=0">RETRY</button></template></div>
 <main><section class="hero"><div class="hero-heading"><div class="eyebrow"><i /> THE DIGITAL ATELIER <span>FIRST LIGHT / 01</span></div><h1>{{s.car.value.name.toUpperCase()}}</h1><div class="hero-sub"><p>Beyond performance.<br>Beyond expectation.</p><span>{{s.car.value.brand.toUpperCase()}}<br>{{s.car.value.engine.toUpperCase()}}</span></div></div>
 <div class="side-label">DESIGNED TO BE EXPERIENCED</div><div class="hero-bottom"><div class="hero-specs"><div><strong>{{s.car.value.power}}<small>CV</small></strong><span>COMBINED POWER</span></div><div><strong>{{s.car.value.accel}}<small>S</small></strong><span>0—100 KM/H</span></div><div><strong>{{s.car.value.speed}}<small>KM/H</small></strong><span>TOP SPEED</span></div></div><a href="#showroom" class="accent-button">ENTER SHOWROOM <span>↗</span></a></div><div class="hero-foot"><a href="#story">↓ <span>SCROLL TO DISCOVER</span></a><span>DRAG TO ROTATE <b>↔</b> SCROLL TO ZOOM</span><small>INTERACTIVE DEVELOPMENT EDITION</small></div></section>
 <section id="story" class="story"><small>01 / SCULPTED BY AIR</small><h2>Every line.<br>A purpose.</h2><p>Form follows a feeling. Explore the interplay of light, surface and motion, from the first sharp edge to the final reflection.</p><div class="story-caption">A NEW PERSPECTIVE ON PERFORMANCE <span>↓</span></div></section>
 <section class="story story-right"><small>02 / DESIGNED FOR MOTION</small><h2>Emotion,<br>engineered.</h2><p>A low silhouette. A commanding stance. A cockpit built around the driver. Move closer and discover the details.</p></section>
 <section id="showroom" class="showroom"><div class="showroom-title"><small>03 / YOUR PERSONAL ATELIER</small><h2>Make it yours.</h2><p>Drag to explore. Choose your expression.</p></div>
 <div class="configurator"><div class="config-heading"><span>CONFIGURE YOUR {{s.car.value.name.toUpperCase()}}</span><span>↗</span></div><div class="config-tabs"><button v-for="t in ['Paint','Wheels','Brakes','Lighting','Interior']" :class="{active:tab===t}" @click="tab=t">{{t}}</button></div><div class="config-content">
 <template v-if="tab==='Paint'"><div class="swatches"><button v-for="p in paints" :aria-label="p.name" :title="p.name" :class="{selected:s.paint.value===p.hex}" :style="{'--swatch':p.hex}" @click="s.paint.value=p.hex" /></div><div class="selection-label"><span>{{paintName}}</span><small>METALLIC FINISH</small></div></template>
 <template v-else-if="tab==='Wheels'"><div class="option-buttons"><button v-for="(w,i) in ['Forged silver','Dark five-spoke','Satin bronze']" :class="{active:s.wheels.value===i}" @click="s.wheels.value=i">{{w}}</button></div></template>
 <template v-else-if="tab==='Brakes'"><div class="swatches"><button v-for="(color,i) in ['#c02a26','#e6d256','#171717','#aaaaaa','#c6e969']" :aria-label="['Red','Yellow','Black','Silver','Acid green'][i]" :style="{'--swatch':color}" :class="{selected:s.brakes.value===color}" @click="s.brakes.value=color" /></div></template>
 <template v-else-if="tab==='Lighting'"><div class="option-buttons"><button v-for="l in ['Studio','Night','Sunset','Dark Room','Garage']" :class="{active:s.lighting.value===l}" @click="s.lighting.value=l">{{l}}</button></div></template>
 <template v-else><button class="outline" @click="s.interior.value=!s.interior.value">{{s.interior.value?'EXIT INTERIOR':'ENTER COCKPIT'}} ↗</button><p>Explore the driver-focused cockpit.</p></template>
 </div><div class="config-actions"><button @click="s.doors.value=!s.doors.value">{{s.doors.value?'CLOSE DOORS':'OPEN DOORS'}} <span>↗</span></button><button @click="start">{{s.engine.value?'STOP':'START'}} ENGINE <span>◉</span></button><button v-if="s.engine.value" @click="audio.sync(true)">REV ↗</button></div></div>
 <div v-if="s.interior.value" class="hotspots"><button v-for="h in ['Steering wheel','Display','Seats','Drive controls','Audio']" @click="hotspot=h">+ {{h}}</button><div v-if="hotspot" class="hotspot-card"><button @click="hotspot=''" aria-label="Close detail">×</button><h3>{{hotspot}}</h3><p>{{{ 'Steering wheel':'A compact racing-inspired wheel puts every control within reach.',Display:'A clear digital instrument panel, centered on the drive.',Seats:'Sculpted sport seats with a dark technical finish.','Drive controls':'An intuitive central console for a focused driving experience.',Audio:'Synthesized engine audio. Enable sound to explore.' }[hotspot]}}</p></div></div>
 </section>
 <section class="collection-cta"><small>THE COLLECTION / 08 MACHINES</small><h2>Eight icons.<br>Endless possibility.</h2><div><NuxtLink to="/garage" class="accent-button">EXPLORE THE GARAGE ↗</NuxtLink><NuxtLink :to="'/drive/'+s.car.value.id" class="outline">TAKE THE WHEEL ↗</NuxtLink></div></section></main>
 <footer><span class="wordmark">VELOCITY 3</span><p>ENGINEERING EMOTION.</p><small>INDEPENDENT CONCEPT EXPERIENCE · 2026<br>Ferrari 458 model: vicent091036 · Three.js examples</small><a href="#">BACK TO TOP ↑</a></footer>
 </div></template>
